def solve(s, k):
    counts = {}
    left = best = maxfreq = 0
    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        maxfreq = max(maxfreq, counts[ch])
        while right - left + 1 - maxfreq > k:
            counts[s[left]] -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

