def solve(n, flights, source, target, k):
    distance = [float("inf")] * n
    distance[source] = 0
    for _ in range(k + 1):
        next_distance = distance.copy()
        for a, b, price in flights:
            next_distance[b] = min(next_distance[b], distance[a] + price)
        distance = next_distance
    return -1 if distance[target] == float("inf") else distance[target]

